code.java:
class Solution {
    public int numberOfSteps(int num){
        int steps=0;
        while(num>0){
            num=num%2==0?num/2:num-1;
            steps++;
        }
        return steps;
    }
}

code.kotlin:
class Solution {
    fun numberOfSteps(numValue:Int):Int{
        var num=numValue;
        var steps=0;
        while(num>0){
            num=if(num%2==0)num/2 else num-1;
            steps++
        };
        return steps
    }
}

